CustomField.formula:
IF(ISNULL(LastActivityDate),
  "⚠ Sem actividade registada",
  IF(TODAY() - LastActivityDate > 60,
    "⚠ Inactivo há " & TEXT(TODAY() - LastActivityDate) & "d",
    IF(TODAY() - LastActivityDate > 30,
      "● " & TEXT(TODAY() - LastActivityDate) & "d sem contacto",
      "✓ Activo — último há " & TEXT(TODAY() - LastActivityDate) & "d"
    )
  )
)
